/**
 * HTTP section of the runtime metadata (`metadata.extensions.http`), generated by the compiler
 * extension `@znight/http/compiler` and consumed by {@link HttpPlugin}. See
 * docs/internals/architecture.md §9.1. Hand-written metadata (tests) must follow the same shape.
 */
import type { Token } from '@znight/core'
import type { HttpContext } from './context.ts'

/** Route methods. `ALL` registers the route for GET, HEAD, POST, PUT, PATCH, DELETE and OPTIONS. */
export type HttpMethod = 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE' | 'HEAD' | 'OPTIONS' | 'ALL'

/**
 * Where a handler parameter comes from (`file` / `files`: `@UploadedFile` / `@UploadedFiles`, the
 * `name` being the multipart field; `cookie` / `signedCookie`: `@Cookie` / `@SignedCookie`, the
 * `name` being the cookie name).
 */
export type HttpParamSource =
  | 'param'
  | 'query'
  | 'body'
  | 'headers'
  | 'request'
  | 'response'
  | 'context'
  | 'file'
  | 'files'
  | 'cookie'
  | 'signedCookie'

/** A handler parameter (informational: extraction, coercion and validation happen in `invoke`). */
export interface HttpParamDefinition {
  /** Position in the handler signature. */
  readonly index: number
  readonly source: HttpParamSource
  /** Parameter / query key / header name (lower case) / multipart field. Absent: the whole object (every field). */
  readonly name?: string
  /** Serialised declared type (`number`, `string[]`, `'asc' | 'desc'`...). */
  readonly type?: string
  readonly optional?: boolean
  /** `true` when the value is validated with a schema. */
  readonly schema?: boolean
}

/**
 * Files accepted by an upload parameter (`@UploadedFile` / `@UploadedFiles`). The plugin enforces
 * these rules while the multipart body is read; the presence of required files is checked by
 * `invoke` (the `uploads` helpers).
 */
export interface HttpUploadDefinition {
  /** Multipart field. Absent: files of any field. */
  readonly field?: string
  /** `true` for `@UploadedFiles` (several files). */
  readonly multiple?: boolean
  /** `true` when a file must be sent (informational, checked by `invoke`). */
  readonly required?: boolean
  /** Maximum size of each file in bytes (`Infinity`: no limit). Default: plugin `uploads.maxFileSize`. */
  readonly maxSize?: number
  /** Maximum number of files (`@UploadedFiles`). Default: plugin `uploads.maxFiles` (1 for `@UploadedFile`). */
  readonly maxFiles?: number
  /** Accepted media types (`image/png`, `image/*`), compared with the type declared by the client. */
  readonly mimeTypes?: readonly string[]
}

/** Options of an `@Sse` route (`HttpRouteDefinition.sse`). */
export interface HttpSseDefinition {
  /** Heartbeat interval in ms (≥ 1 000); `0` disables it. Absent: the plugin option `sse.heartbeat`. */
  readonly heartbeat?: number
  /** `retry` sent first (ms). Absent: the plugin option `sse.retry`. */
  readonly retry?: number
  /** The stream ends gracefully after this many ms (≥ 1 000). */
  readonly maxDuration?: number
}

/** A route: one decorated method of a controller. */
export interface HttpRouteDefinition {
  readonly method: HttpMethod
  /** Path of the route decorator, normalised (`/:id`). */
  readonly path: string
  /** `joinPaths(controller.basePath, path)` (without the plugin `prefix`). */
  readonly fullPath: string
  /** Name of the handler method. */
  readonly handler: string
  /** `@HttpCode(status)`. */
  readonly status?: number
  /** `@Header(name, value)` entries (names in lower case). */
  readonly headers?: Readonly<Record<string, string>>
  /**
   * Route metadata (`createRouteDecorator`), merged over the controller metadata at runtime, one
   * decision per group: the route's entry of a group replaces the controller's entries of that group
   * (see {@link HttpMetadata.groups}).
   */
  readonly meta: Readonly<Record<string, unknown>>
  /** Route guards (provider tokens), run after global and controller guards. */
  readonly guards: readonly Token[]
  /** Route interceptors (provider tokens), innermost. */
  readonly interceptors: readonly Token[]
  readonly params: readonly HttpParamDefinition[]
  /**
   * `@BodyLimit` (route or controller): maximum body size in bytes (`Infinity`: no limit). Default:
   * the plugin `bodyLimit`, or for upload routes the sum of the file limits plus `bodyLimit`.
   */
  readonly bodyLimit?: number
  /**
   * Upload rules (one per `@UploadedFile` / `@UploadedFiles` parameter). Routes with uploads parse
   * `multipart/form-data` bodies before the interceptors and answer 415 to other non-empty bodies.
   */
  readonly uploads?: readonly HttpUploadDefinition[]
  /** `true` when the handler takes `@Res()` and writes the response itself. */
  readonly rawResponse?: boolean
  /**
   * `@Sse` route (GET only): the handler result (an `AsyncIterable`, an `Iterable` or a
   * `ReadableStream` of `SseEvent`) is served as an event stream; an `HttpResponse` or a Web
   * `Response` is sent as usual. `{}` without options.
   */
  readonly sse?: HttpSseDefinition
  /**
   * Calls the handler: extracts, coerces and validates every argument from the context, then calls
   * the method on the controller instance. May return a promise.
   */
  // biome-ignore lint/suspicious/noExplicitAny: generated functions take the concrete controller class
  readonly invoke: (controller: any, ctx: HttpContext) => unknown
}

/** A controller: a provider whose methods are routes. */
export interface HttpControllerDefinition {
  /** Provider token of the controller class. */
  readonly token: Token
  /** Normalised base path (`/users`, `/` when absent). */
  readonly basePath: string
  /** Controller guards (provider tokens). */
  readonly guards: readonly Token[]
  /** Controller interceptors (provider tokens). */
  readonly interceptors: readonly Token[]
  /** Controller metadata (`createRouteDecorator` on the class). */
  readonly meta: Readonly<Record<string, unknown>>
  readonly routes: readonly HttpRouteDefinition[]
}

/** A route decorator group (`createRouteDecorator(key, { group, required })`). */
export interface HttpRouteGroupDefinition {
  /** Keys of the decorators of the group, sorted. */
  readonly keys: readonly string[]
  /** Every route must carry a decision of the group. */
  readonly required: boolean
}

/** `metadata.extensions.http`. */
export interface HttpMetadata {
  readonly controllers: readonly HttpControllerDefinition[]
  /**
   * Route decorator groups that need to be known at runtime (required, holding several keys, or
   * named differently from their key): group → `{ keys, required }`. A key belongs to one group at
   * most; a key listed nowhere is its own group. Absent when no group needs it.
   */
  readonly groups?: Readonly<Record<string, HttpRouteGroupDefinition>>
}

declare module '@znight/core' {
  interface ZnightExtensionsMetadata {
    readonly http?: HttpMetadata
  }
}
